pub struct EcosystemLocationStruct {
    pub unique_location_id: String,
    pub location_descriptor: globals::LocationDescriptorStruct,
    pub location_descriptor_last_edit: types::EpochUs,
}

impl EcosystemLocationStruct {
    pub const FIELD_LOCATION_DESCRIPTOR: FieldId = FieldId::new(0x1);
    pub const FIELD_LOCATION_DESCRIPTOR_LAST_EDIT: FieldId = FieldId::new(0x2);
    pub const FIELD_UNIQUE_LOCATION_ID: FieldId = FieldId::new(0x0);

    #[must_use]
    pub fn new(
        unique_location_id: impl Into<String>,
        location_descriptor: impl Into<globals::LocationDescriptorStruct>,
        location_descriptor_last_edit: impl Into<types::EpochUs>,
    ) -> Self {
        Self {
            unique_location_id: unique_location_id.into(),
            location_descriptor: location_descriptor.into(),
            location_descriptor_last_edit: location_descriptor_last_edit.into(),
        }
    }

    pub(crate) fn decode_fields_inner(
        fields: Vec<(FieldId, AttributeValue)>,
    ) -> Result<Self, (Option<FieldId>, MatterStatus)> {
        let mut unique_location_id = None;
        let mut location_descriptor = None;
        let mut location_descriptor_last_edit = None;
        for (fid, fval) in fields {
            match fid.raw() {
                0 => {
                    if unique_location_id.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <String>::try_from(fval)?;
                        (decoded.len() <= 64)
                            .then_some(())
                            .ok_or(MatterStatus::ConstraintError)?;
                        unique_location_id = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                1 => {
                    if location_descriptor.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <globals::LocationDescriptorStruct>::try_from(fval)?;
                        location_descriptor = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                2 => {
                    if location_descriptor_last_edit.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <types::EpochUs>::try_from(fval)?;
                        location_descriptor_last_edit = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                _ => return Err((Some(fid), MatterStatus::ConstraintError)),
            }
        }
        Ok(Self {
            unique_location_id: unique_location_id.ok_or((Some(FieldId::new(0)), MatterStatus::ConstraintError))?,
            location_descriptor: location_descriptor.ok_or((Some(FieldId::new(1)), MatterStatus::ConstraintError))?,
            location_descriptor_last_edit: location_descriptor_last_edit
                .ok_or((Some(FieldId::new(2)), MatterStatus::ConstraintError))?,
        })
    }

    pub(crate) fn encode_fields_inner(self) -> Vec<(FieldId, AttributeValue)> {
        alloc::vec![
            (
                Self::FIELD_UNIQUE_LOCATION_ID,
                AttributeValue::from(self.unique_location_id)
            ),
            (
                Self::FIELD_LOCATION_DESCRIPTOR,
                AttributeValue::from(self.location_descriptor)
            ),
            (
                Self::FIELD_LOCATION_DESCRIPTOR_LAST_EDIT,
                AttributeValue::from(self.location_descriptor_last_edit)
            ),
        ]
    }
}

impl From<EcosystemLocationStruct> for AttributeValue {
    #[inline]
    fn from(val: EcosystemLocationStruct) -> Self {
        AttributeValue::Struct(val.encode_fields_inner())
    }
}

impl TryFrom<AttributeValue> for EcosystemLocationStruct {
    type Error = MatterStatus;

    #[inline]
    fn try_from(val: AttributeValue) -> Result<Self, MatterStatus> {
        let AttributeValue::Struct(fields) = val else {
            return Err(MatterStatus::InvalidDataType);
        };
        Self::decode_fields_inner(fields).map_err(|(_, status)| status)
    }
}

